import attr
from typing import Optional, Union

from .networkaddress import NetworkAddress
from ..connection_details import SshServiceDetails, HttpConnectionDetails


@attr.s(cmp=False)
class CU(object):
    """Model of the CU created by the CuProvider from the OpenStack .env files.
     oam_vm is created from parsing the heat templates

    :param str backhaul_site_oam_ip: ip address or details (ips & vlan) for oam network
    :param SshServiceDetails oam_ssh_connection_details: SshServiceDetails class instance object
    :param HttpConnectionDetails oam_http_connection_details: HttpConnectionDetails class instance object
    :param NetworkAddress f1m: Details (ips & vlan) for f1m network
    :param NetworkAddress f1c: Details (ips & vlan) for f1c network
    :param NetworkAddress f1u: Details (ips & vlan) for f1u network
    :param NetworkAddress x2c: Details (ips & vlan) for x2c network
    :param NetworkAddress x2u: Details (ips & vlan) for x2u network
    :param NetworkAddress s1c: Details (ips & vlan) for s1c network
    :param NetworkAddress s1u: Details (ips & vlan) for s1u network
    :param NetworkAddress tracing: Details (ips & vlan) for tracing network
    :param NetworkAddress xnc: Details (ips & vlan) for xnc network
    :param NetworkAddress xnu: Details (ips & vlan) for xnu network
    :param NetworkAddress ngc: Details (ips & vlan) for ngc network
    :param NetworkAddress ngu: Details (ips & vlan) for ngu network
    :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
    :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
        It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
    """

    backhaul_site_oam_ip = attr.ib(type=Union[NetworkAddress, str])
    oam_ssh_connection_details = attr.ib(type=SshServiceDetails)
    oam_http_connection_details = attr.ib(type=HttpConnectionDetails)
    f1m = attr.ib(default=None, type=Optional[NetworkAddress])
    f1c = attr.ib(default=None, type=Optional[NetworkAddress])
    f1u = attr.ib(default=None, type=Optional[NetworkAddress])
    x2c = attr.ib(default=None, type=Optional[NetworkAddress])
    x2u = attr.ib(default=None, type=Optional[NetworkAddress])
    s1c = attr.ib(default=None, type=Optional[NetworkAddress])
    s1u = attr.ib(default=None, type=Optional[NetworkAddress])
    tracing = attr.ib(default=None, type=Optional[NetworkAddress])
    xnc = attr.ib(default=None, type=Optional[NetworkAddress])
    xnu = attr.ib(default=None, type=Optional[NetworkAddress])
    ngc = attr.ib(default=None, type=Optional[NetworkAddress])
    ngu = attr.ib(default=None, type=Optional[NetworkAddress])
    instance_id = attr.ib(default=None, type=Optional[int])
    global_bts_id = attr.ib(default=None, type=Optional[int])
